#include <iostream>

class ClassA { public: ~ClassA() { std::cout << "Cleaned up.\n"; } };

void safe_manual_f() {
    ClassA* ptr = new ClassA; 
    try {
        // Operations
        std::cout << "Performing work...\n";
        // throw std::runtime_error("Failure"); // Uncomment to test exception path
    } 
    catch (...) { // Catch any exception
        delete ptr; // Cleanup (Exception path)
        throw;      // Rethrow to continue unwinding
    }
    delete ptr;     // Cleanup (Normal path)
}

int main() {
    try { safe_manual_f(); } catch (...) { /* caught */ }
}
